import{d as b,C as r,o as _,c as f,a3 as o,E as i,j as a,a as t}from"./chunks/framework.Q4yG9rk_.js";const T=JSON.parse('{"title":"庄子·缮性","description":"从蔽蒙之民到倒置之民，沿知恬交养、存身正己与古今得志之辨，理解本性与外物的关系。","frontmatter":{"title":"庄子·缮性","description":"从蔽蒙之民到倒置之民，沿知恬交养、存身正己与古今得志之辨，理解本性与外物的关系。","category":"guide","aliases":["缮性","庄子缮性","zhuangzi chapter 16"],"source":["《庄子·缮性》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-16.md","filePath":"daoism/zhuang-zi/chapter-16.md","lastUpdated":1792641266000}'),q={name:"daoism/zhuang-zi/chapter-16.md"},v=b({...q,setup(k){const x=[{id:"shanxing-bimeng",sentences:[[{text:"缮性",glossary:"shanxing"},"于",{text:"俗学",glossary:"suxue"},"，以求复其初；",{text:"滑欲",glossary:"guyu"},"于",{text:"俗思",glossary:"susi"},"，以求致其明：谓之",{text:"蔽蒙",glossary:"bimeng"},"之民。"]]}],l=[{id:"shanxing",term:"缮性",pinyin:["shàn","xìng"],meaning:"修治本性；缮，修治。"},{id:"suxue",term:"俗学",pinyin:["sú","xué"],meaning:"世俗的学问；此处与回归本初的目标相对。"},{id:"guyu",term:"滑欲",pinyin:["gǔ","yù"],meaning:"扰乱欲念；滑在本段按扰乱、搅动理解。"},{id:"susi",term:"俗思",pinyin:["sú","sī"],meaning:"世俗的思虑计较。"},{id:"bimeng",term:"蔽蒙",pinyin:["bì","méng"],meaning:"受遮蔽而蒙昧不明。"}],m=[{id:"shanxing-knowledge",label:"一、知恬交养·和理出性",sentences:[["古之治道者，以",{text:"恬",glossary:"tian_shanxing"},"养",{text:"知",glossary:"zhi_shanxing"},"。生而无以知为也，谓之以知养恬。"],["知与恬交相养，而",{text:"和理",glossary:"heli_shanxing"},"出其性。"]]},{id:"shanxing-virtue",label:"二、德兼于道·礼乐则乱",sentences:[["夫德，和也；道，理也。德无不容，仁也；道无不理，义也；"],["义明而物亲，忠也；中",{text:"纯实",glossary:"zhongchunshi_shanxing"},"而",{text:"反",glossary:"fanqing_shanxing"},"乎情，乐也；"],["信行",{text:"容体",glossary:"xinxingrongti_shanxing"},"而顺乎文，礼也。礼乐遍行，则天下乱矣。"],["彼正而蒙己德，德则不",{text:"冒",glossary:"mao_shanxing"},"。冒则物必失其性也。"]]},{id:"shanxing-unity",label:"三、至一之世",sentences:[["古之人，在",{text:"混芒",glossary:"hunmang_shanxing"},"之中，与一世而得",{text:"淡漠",glossary:"danmo_shanxing"},"焉。"],["当是时也，阴阳和静，鬼神不扰，四时得节，万物不伤，群生不夭，人虽有知，无所用之，"],["此之谓",{text:"至一",glossary:"zhiyi_shanxing"},"。当是时也，莫之为而常自然。"]]},{id:"shanxing-decline",label:"四、德之下衰·递降与惑乱",sentences:[[{text:"逮",glossary:"dai_shanxing"},"德下衰，及燧人、伏羲始为天下，是故顺而不一。"],["德又下衰，及神农、黄帝始为天下，是故安而不顺。"],["德又下衰，及唐、虞始为天下，兴",{text:"治化",glossary:"zhihua_shanxing"},"之流，",{text:"枭淳",glossary:"xiaochunsanpu_shanxing"},{text:"散朴",glossary:"sanpu_shanxing"},"，离道以善，",{text:"险",glossary:"xiandeyixing_shanxing"},"德以行，然后去性而从于心。"],["心与心识知，而不足以定天下，然后附之以文，益之以博。"],["文灭质，博",{text:"溺",glossary:"bonixin_shanxing"},"心，然后民始惑乱，无以反其性情而复其初。"],["由是观之，世丧道矣，道丧世矣，世与道交相丧也。"]]}],g=[{id:"tian_shanxing",term:"恬",pinyin:["tián"],meaning:"恬静、安静；此处指不妄动的精神状态。"},{id:"zhi_shanxing",term:"知",pinyin:["zhì"],meaning:"知性、智识；此处通“智”。"},{id:"heli_shanxing",term:"和理",pinyin:["hé","lǐ"],meaning:"和谐的条理，从本性自然流出。"},{id:"zhongchunshi_shanxing",term:"纯实",pinyin:["chún","shí"],meaning:"纯粹真实；此处形容内心。"},{id:"fanqing_shanxing",term:"反",pinyin:["fǎn"],meaning:"归返；此处指回到真情本然。"},{id:"xinxingrongti_shanxing",term:"容体",pinyin:["róng","tǐ"],meaning:"仪容与形体。"},{id:"mao_shanxing",term:"冒",pinyin:["mào"],meaning:"覆盖、强加；以外物遮蔽本性。"},{id:"hunmang_shanxing",term:"混芒",pinyin:["hùn","máng"],meaning:"混沌未分而朴素浑全。"},{id:"danmo_shanxing",term:"淡漠",pinyin:["dàn","mò"],meaning:"恬淡寂漠，无执无求。"},{id:"zhiyi_shanxing",term:"至一",pinyin:["zhì","yī"],meaning:"天地万物浑然一体的状态。"},{id:"dai_shanxing",term:"逮",pinyin:["dài"],meaning:"及至、到了。"},{id:"zhihua_shanxing",term:"治化",pinyin:["zhì","huà"],meaning:"治理与教化。"},{id:"xiaochunsanpu_shanxing",term:"枭淳",pinyin:["xiāo","chún"],meaning:"毁损淳厚；枭，毁损。"},{id:"sanpu_shanxing",term:"散朴",pinyin:["sàn","pǔ"],meaning:"离散朴素。"},{id:"xiandeyixing_shanxing",term:"险",pinyin:["xiǎn"],meaning:"危损；此处指行为危损德性。"},{id:"bonixin_shanxing",term:"溺",pinyin:["nì"],meaning:"淹没；此处写博识对本心的遮蔽。"}],u=[{id:"shanxing-hidden-virtue",label:"一、世道交相丧·德隐",sentences:[[{text:"道之人",glossary:"daozhiren_shanxing"},"何由兴乎世，世亦何由兴乎道哉！"],["道无以兴乎世，世无以兴乎道，虽圣人不在山林之中，其德隐矣。"]]},{id:"shanxing-timing",label:"二、隐非伏身·时命大谬",sentences:[["隐故不自隐。"],["古之所谓隐士者，非",{text:"伏",glossary:"fu_shanxing"},"其身而弗见也，非闭其言而不出也，非藏其知而不发也，",{text:"时命",glossary:"shiming_shanxing"},{text:"大谬",glossary:"damiu_shanxing"},"也。"]]},{id:"shanxing-preservation",label:"三、存身之道",sentences:[["当时命而大行乎天下，则",{text:"反一",glossary:"fanyi_shanxing"},"无迹；"],["不当时命而",{text:"大穷",glossary:"daqiong_shanxing"},"乎天下，则",{text:"深根",glossary:"shengen_shanxing"},{text:"宁极",glossary:"ningji_shanxing"},"而待：此存身之道也。"]]},{id:"shanxing-self-correction",label:"四、正己而已·乐全得志",sentences:[["古之存身者，不以",{text:"辩饰",glossary:"bianshi_shanxing"},"知，不以知穷天下，不以知穷德，",{text:"危然",glossary:"weiran_shanxing"},"处其所而反其性，己又何为哉！"],["道固不",{text:"小行",glossary:"xiaoxing_shanxing"},"，德固不",{text:"小识",glossary:"xiaoshi_shanxing"},"。小识伤德，小行伤道。"],["故曰：正己而已矣。",{text:"乐全",glossary:"lequan_shanxing"},"之谓得志。"]]}],h=[{id:"daozhiren_shanxing",term:"道之人",pinyin:["dào","zhī","rén"],meaning:"体道之人，以道为本的人。"},{id:"fu_shanxing",term:"伏",pinyin:["fú"],meaning:"隐伏、藏匿；此处指藏起形迹。"},{id:"shiming_shanxing",term:"时命",pinyin:["shí","mìng"],meaning:"时机与命运，指人的处境与际遇。"},{id:"damiu_shanxing",term:"大谬",pinyin:["dà","miù"],meaning:"大为乖违、不相合。"},{id:"fanyi_shanxing",term:"反一",pinyin:["fǎn","yī"],meaning:"反归浑一；反，归返。"},{id:"daqiong_shanxing",term:"大穷",pinyin:["dà","qióng"],meaning:"极度困窘，处处受阻。"},{id:"shengen_shanxing",term:"深根",pinyin:["shēn","gēn"],meaning:"深固根本。"},{id:"ningji_shanxing",term:"宁极",pinyin:["níng","jí"],meaning:"安守极静。"},{id:"bianshi_shanxing",term:"辩饰",pinyin:["biàn","shì"],meaning:"以辩说修饰、炫耀。"},{id:"weiran_shanxing",term:"危然",pinyin:["wēi","rán"],meaning:"端正自守的样子；危，此处指端正。"},{id:"xiaoxing_shanxing",term:"小行",pinyin:["xiǎo","xíng"],meaning:"局部、片面的作为。"},{id:"xiaoshi_shanxing",term:"小识",pinyin:["xiǎo","shí"],meaning:"局部、片面的识见。"},{id:"lequan_shanxing",term:"乐全",pinyin:["lè","quán"],meaning:"以保全本性、保持完整为乐。"}],y=[{id:"shanxing-fulfillment",label:"一、古今得志之辨",sentences:[["古之所谓得志者，非",{text:"轩冕",glossary:"xuanmian_shanxing"},"之谓也，谓其无以益其乐而已矣。"],["今之所谓得志者，轩冕之谓也。"]]},{id:"shanxing-temporary-gains",label:"二、寄也·其乐彼与此同",sentences:[["轩冕在身，非",{text:"性命",glossary:"xingming_shanxing"},"也，物之",{text:"傥来",glossary:"tanglai_shanxing"},"，",{text:"寄",glossary:"ji_shanxing"},"也。"],["寄之，其来不可",{text:"圉",glossary:"yu_shanxing"},"，其去不可止。"],["故不为轩冕",{text:"肆志",glossary:"sizhi_shanxing"},"，不为",{text:"穷约",glossary:"qiongyue_shanxing"},{text:"趋俗",glossary:"qusu_shanxing"},"，其乐彼与此同，故无忧而已矣！"],["今寄去则不乐。由是观之，虽乐，未尝不",{text:"荒",glossary:"huang_shanxing"},"也。"]]},{id:"shanxing-inversion",label:"三、倒置之民",sentences:[["故曰：丧己于物，失性于俗者，谓之",{text:"倒置",glossary:"daozhi_shanxing"},"之民。"]]}],p=[{id:"xuanmian_shanxing",term:"轩冕",pinyin:["xuān","miǎn"],meaning:"轩是卿大夫之车，冕是礼冠；此处代指功名富贵。"},{id:"xingming_shanxing",term:"性命",pinyin:["xìng","mìng"],meaning:"本性与天命；此处与外来的轩冕相对。"},{id:"tanglai_shanxing",term:"傥来",pinyin:["tǎng","lái"],meaning:"偶然而来，非本然所有。"},{id:"ji_shanxing",term:"寄",pinyin:["jì"],meaning:"暂时寄放；此处形容外物的暂存。"},{id:"yu_shanxing",term:"圉",pinyin:["yǔ"],meaning:"阻止、拦截。"},{id:"sizhi_shanxing",term:"肆志",pinyin:["sì","zhì"],meaning:"放纵志意。"},{id:"qiongyue_shanxing",term:"穷约",pinyin:["qióng","yuē"],meaning:"处境困顿贫乏。"},{id:"qusu_shanxing",term:"趋俗",pinyin:["qū","sú"],meaning:"趋附世俗。"},{id:"huang_shanxing",term:"荒",pinyin:["huāng"],meaning:"荒废、迷失；此处指本性失落。"},{id:"daozhi_shanxing",term:"倒置",pinyin:["dào","zhì"],meaning:"颠倒本末，把外物与世俗置于自身本性之上。"}];return(P,n)=>{const c=r("DaoReadingPrelude"),s=r("DaoTextReading"),e=r("DaoKeywordCards"),d=r("DaoLineGuide");return _(),f("div",null,[n[0]||(n[0]=o("",4)),i(c,{title:"从蔽蒙之民读到倒置之民",summary:"《缮性》先追问俗学、俗思与复初、致明的方法错位，再写知恬交养与德之下衰。世道交丧之后，文本转入存身正己，最后借轩冕与乐全的对照，把得志的尺度放回本性的完整。",points:[{label:"先看",text:"求本求明为什么落入蔽蒙，知恬交养怎样提供另一条线索？"},{label:"再问",text:"德之下衰与世道交丧之后，存身、反性和正己怎样相接？"},{label:"最后",text:"轩冕为何被称为寄，乐全与外在得志又有何不同？"}],hint:"按四大模块依次读，留意开篇蔽蒙、篇末倒置与中间正己乐全的照应。"}),n[1]||(n[1]=a("h2",{id:"一、蔽蒙之民",tabindex:"-1"},[t("一、蔽蒙之民 "),a("a",{class:"header-anchor",href:"#一、蔽蒙之民","aria-label":'Permalink to "一、蔽蒙之民"'},"​")],-1)),n[2]||(n[2]=a("h3",{id:"原文",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),i(s,{sections:x,glossary:l,"default-mode":"classic","aria-label":"缮性·蔽蒙之民 原文"}),n[3]||(n[3]=a("h3",{id:"生僻字词",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(e,{items:l}),n[4]||(n[4]=a("h3",{id:"核心句引读",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(d,{title:"两组错位，一个判词",subtitle:"从缮性与滑欲，到复初与致明，最后以蔽蒙揭示方法与目标的矛盾。",lines:[{text:"缮性于俗学，以求复其初；",tone:"一·缮性与复初",guide:"缮性是修治本性，复其初是回到本初；问题落在“于俗学”这一方法上。依本段的阅读线索，俗学可从礼教、名分与后天规范等方面理解：若本性已经受这些规范遮蔽，又借它们求复初，便形成以增加外在塑造来求回归的张力。"},{text:"滑欲于俗思，以求致其明：",tone:"二·滑欲与致明",guide:"滑在此读 gǔ，按扰乱、搅动理解。致其明是求得心智的明澈，所借助的却是俗思的分别、权衡与计较。越想用这些思虑整顿欲念，越可能继续搅动它们；这与上一句构成方法和目标的对照。"},{text:"谓之蔽蒙之民。",tone:"三·蔽蒙的判断",guide:"两组句子最后落在同一个判断：求本与求明的愿望，却可能被所用的方法遮蔽。把第一组读作“蔽”、第二组读作“蒙”，可以帮助记忆这个结构；原文则将两者合称为“蔽蒙之民”。真正的缮性如何展开，是本段留给后文的问题。"}]}),n[5]||(n[5]=a("h2",{id:"二、知恬交养·至一之世·德之下衰",tabindex:"-1"},[t("二、知恬交养·至一之世·德之下衰 "),a("a",{class:"header-anchor",href:"#二、知恬交养·至一之世·德之下衰","aria-label":'Permalink to "二、知恬交养·至一之世·德之下衰"'},"​")],-1)),n[6]||(n[6]=a("h3",{id:"原文-1",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),i(s,{sections:m,glossary:g,"default-mode":"classic","aria-label":"缮性·知恬交养与德之下衰 原文"}),n[7]||(n[7]=a("h3",{id:"生僻字词-1",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(e,{items:g}),n[8]||(n[8]=a("h3",{id:"核心句引读-1",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(d,{title:"从知恬交养到世道交相丧",subtitle:"第二段先写知与恬互相涵养，再写礼乐形式如何遮蔽德道，最后以德之递降说明世与道的相互丧失。",lines:[{text:"古之治道者，以恬养知。生而无以知为也，谓之以知养恬。",tone:"一·知恬交养",guide:"这一段先把第一段的“俗思”换成知与恬的相养：知不被用来妄为，恬也不被理解为抛弃知性。二者交相涵养，才可能让和理从本性自然流出；这是对“缮性”方法的第一次正面展开。"},{text:"礼乐遍行，则天下乱矣。彼正而蒙己德，德则不冒。冒则物必失其性也。",tone:"二·德道与礼乐",guide:"德与道分别以“和”和“理”概括，仁、义、忠、乐、礼则被写成由内向外的展开。礼乐本可被理解为德道的外在表现，但遍行之后可能反过来覆盖本性。“正而蒙己德”与“德则不冒”的关系尚待核对；这里先联系下一句，留意外加的规范如何使万物失性。具体训诂与句意留待精校。"},{text:"古之人，在混芒之中，与一世而得淡漠焉。",tone:"三·至一之世",guide:"混芒、淡漠、至一共同描绘一个不靠人为治理维持的状态：阴阳和静、四时得节、万物不伤，人的知性也无所用之。重点不是赞美愚昧，而是呈现“莫之为而常自然”的秩序。"},{text:"由是观之，世丧道矣，道丧世矣，世与道交相丧也。",tone:"四·递降与交相丧",guide:"燧人伏羲写顺而不一，神农黄帝写安而不顺，唐虞之后转向治化、礼文与博识，最终文灭质、博溺心。结尾并非只说世间失道，也说“道丧世”，指出世与道在分离中彼此失去承载。"}]}),n[9]||(n[9]=a("h2",{id:"三、世道交丧·存身正己",tabindex:"-1"},[t("三、世道交丧·存身正己 "),a("a",{class:"header-anchor",href:"#三、世道交丧·存身正己","aria-label":'Permalink to "三、世道交丧·存身正己"'},"​")],-1)),n[10]||(n[10]=a("h3",{id:"原文-2",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),i(s,{sections:u,glossary:h,"default-mode":"classic","aria-label":"缮性·世道交丧与存身正己 原文"}),n[11]||(n[11]=a("h3",{id:"生僻字词-2",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(e,{items:h}),n[12]||(n[12]=a("h3",{id:"核心句引读-2",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(d,{title:"从德隐于世到正己乐全",subtitle:"先分清德隐与身隐，再看时命相合或乖违时如何存身，最后落到反性、正己与乐全。",lines:[{text:"道无以兴乎世，世无以兴乎道，虽圣人不在山林之中，其德隐矣。",tone:"一·世道交丧与德隐",guide:"承接上一段世与道交相丧，两个“何由”追问体道者与世间如何相互成就。圣人即使身在人群之中，德也可能无从显现；这里的“隐”首先写德与时世的关系，不能只看作退居山林。"},{text:"古之所谓隐士者，非伏其身而弗见也，非闭其言而不出也，非藏其知而不发也，时命大谬也。",tone:"二·隐非自隐",guide:"“隐故不自隐”之后，三个“非”依次排除刻意藏身、闭言、藏知的读法。原文把隐的原因落在时命不合上：读者可继续追问，怎样辨别顺应处境的隐与以隐自我标榜的姿态。"},{text:"当时命而大行乎天下，则反一无迹；不当时命而大穷乎天下，则深根宁极而待：此存身之道也。",tone:"三·行与待",guide:"时命相合，可以大行而反一无迹；时命不合，则深固根本、安守极静而待。两种处境共同指向存身：既留意保存自身，也联系下文“反其性”，理解为在行动或困顿中保全本性。"},{text:"道固不小行，德固不小识。小识伤德，小行伤道。故曰：正己而已矣。乐全之谓得志。",tone:"四·正己与乐全",guide:"前文三个“不以”提醒人留意以辩说炫耀智识、以智识穷究天下与德的限度。“危然处其所而反其性”由此转回端正自守。小识与小行若被当成全部，便可能伤德伤道；结尾以正己、乐全回应缮性，也为下一段得志之辨留下入口。"}]}),n[13]||(n[13]=a("h2",{id:"四、得志非轩冕·倒置之民",tabindex:"-1"},[t("四、得志非轩冕·倒置之民 "),a("a",{class:"header-anchor",href:"#四、得志非轩冕·倒置之民","aria-label":'Permalink to "四、得志非轩冕·倒置之民"'},"​")],-1)),n[14]||(n[14]=a("h3",{id:"原文-3",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),i(s,{sections:y,glossary:p,"default-mode":"classic","aria-label":"缮性·得志非轩冕与倒置之民 原文"}),n[15]||(n[15]=a("h3",{id:"生僻字词-3",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),i(e,{items:p}),n[16]||(n[16]=a("h3",{id:"核心句引读-3",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),i(d,{title:"从乐全得志到外物暂寄",subtitle:"古今得志的对照，落在快乐能否随外物来去保持完整，最终以倒置照应蔽蒙。",lines:[{text:"古之所谓得志者，非轩冕之谓也，谓其无以益其乐而已矣。",tone:"一·古今得志",guide:"承接上段“乐全之谓得志”，古之得志以本性完整之乐为尺度，外物已无可增益；今之得志则被写成轩冕。两种尺度一内一外，读者可据此追问，自己如何判断是否得志。"},{text:"轩冕在身，非性命也，物之傥来，寄也。寄之，其来不可圉，其去不可止。",tone:"二·外物是寄",guide:"轩冕即使加在身上，也与性命有别。傥来写偶然而得，寄写暂时停留，来不可圉、去不可止则写人不能将它完全据为己有。这个比喻为后文如何面对得失建立根据。"},{text:"故不为轩冕肆志，不为穷约趋俗，其乐彼与此同，故无忧而已矣！",tone:"三·得失同乐",guide:"有轩冕时不放纵志意，处穷约时不趋附世俗，两种处境中仍保持同样的乐。今人却在寄去之后不乐，于是“虽乐，未尝不荒”：若快乐完全依附于外物，本性就可能在得失之间持续失落。"},{text:"故曰：丧己于物，失性于俗者，谓之倒置之民。",tone:"四·倒置与蔽蒙",guide:"结尾以丧己于物、失性于俗给倒置下定义，照应开篇借俗学俗思求本求明的蔽蒙。我把这组首尾关系读作从“用末求本”到“以末为本”的对照，回应之道则落在知恬交养、反性正己与乐全。"}]}),n[17]||(n[17]=o("",35))])}}});export{T as __pageData,v as default};
